css:
.bko{--p:#2f9d66;--pd:#1f7d4e;--pl:#eefcf5;--pl2:#d9f8e8;--line:#b0e3c9;--ink:#17251e;--gr:#485d52;--hl:#fff06b;--wa:#f2b400;--wl:#fff8dc;--y:#ffca2c;--yd:#8a6500}
*{box-sizing:border-box}.bko{-webkit-print-color-adjust:exact;print-color-adjust:exact}
@page{size:A4;margin:0}.bko{margin:0;background:#dfeee6;font-family:Pretendard,'Noto Sans CJK KR','Malgun Gothic','Apple SD Gothic Neo',sans-serif;color:var(--ink);font-size:10.5pt;line-height:1.62;font-weight:400;--gl:0mm;--gr2:0mm;word-break:keep-all;overflow-wrap:break-word}
.page{position:relative;width:210mm;height:297mm;margin:6mm auto;background:#fff;overflow:hidden;break-after:page;page-break-after:always;box-shadow:0 2px 10px rgba(30,50,80,.22)}
@media print{.bko{background:#fff}.page{margin:0;box-shadow:none}.page:last-child{break-after:auto;page-break-after:auto}}
.page{--gl:0mm;--gr2:0mm}
.page.odd{--gl:3mm}
.page.even{--gr2:3mm}
.hdr{position:absolute;top:8mm;left:calc(12mm + var(--gl));right:calc(12mm + var(--gr2));height:6mm;display:flex;justify-content:space-between;align-items:flex-end;font-size:9.5pt;color:var(--gr);padding-bottom:1mm;font-weight:400;border-bottom:.25mm solid var(--line)}
.hdr::after{display:none}
.hdr b{color:var(--ink);font-weight:500}
.hdr .hr{color:var(--pd);font-weight:500}
.page.even .hdr{flex-direction:row}
.ftr{position:absolute;bottom:8mm;left:calc(12mm + var(--gl));right:calc(12mm + var(--gr2));display:flex;align-items:baseline;justify-content:space-between;font-size:9pt;color:var(--gr);font-weight:400}
.ftr::before{content:"";position:absolute;left:0;right:0;top:-3mm;border-top:.2mm solid var(--line)}
.ftr .pn{color:var(--p);font-weight:500;font-size:11pt;letter-spacing:.2mm}
.ftr .pt{color:var(--gr);font-weight:400;letter-spacing:.2mm}
.ftr .pt::before{content:"";display:inline-block;width:1.6mm;height:1.6mm;background:var(--y);margin-right:1.8mm;border-radius:50%}
.page.odd .ftr{flex-direction:row}
.page.odd .ftr .pt{order:0}.page.odd .ftr .pn{order:1}
.page.even .ftr .pt{order:1}.page.even .ftr .pn{order:0}
.bd{position:absolute;top:18mm;left:calc(12mm + var(--gl));right:calc(12mm + var(--gr2));bottom:16mm}
.bd .col{position:relative;height:100%;overflow:hidden}
.bd.two{display:flex;gap:0}
.bd.two .col{width:50%;flex:none}
.bd.two .col:first-child{padding-right:4.2mm;border-right:.25mm solid var(--line)}
.bd.two .col:last-child{padding-left:4.2mm}
sub,sup{font-size:.9em;line-height:0}
p{margin:0 0 1.6mm}
b,strong{font-weight:500}
.hl{background:linear-gradient(transparent 36%,var(--hl) 36%,var(--hl) 94%,transparent 94%);padding:0 .3mm;font-weight:500;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.fr{text-indent:0;display:inline-block;vertical-align:middle;text-align:center;line-height:1.12;margin:0 .12em}
.fr>span{display:block;padding:0 .18em}
.fr>span:first-child{border-bottom:.2mm solid currentColor}
.tp{white-space:nowrap}
/* headings */
h2.sec{margin:0 0 3mm;padding:1.8mm 0 1.4mm;font-size:17pt;font-weight:700;color:var(--ink);border-top:1.2mm solid var(--p);border-bottom:.3mm solid var(--line);display:flex;align-items:baseline;gap:3mm;line-height:1.25}
h2.sec .no{color:var(--p);font-size:17pt}
h2.sec small{margin-left:auto;font-size:10.5pt;font-weight:500;color:var(--gr)}
h3.sub{margin:3.2mm 0 2mm;font-size:13pt;font-weight:700;display:flex;align-items:center;gap:2.4mm;color:var(--ink);line-height:1.3}
h3.sub i{font-style:normal;flex:none;width:7.2mm;height:7.2mm;line-height:7.2mm;text-align:center;background:var(--p);color:#fff;font-size:12pt;font-weight:700}
h3.sub span.ref{margin-left:auto;font-size:10pt;font-weight:500;color:var(--gr)}
h4{margin:2.4mm 0 1mm;font-size:11pt;font-weight:700;color:var(--pd)}
h4::before{content:"";display:inline-block;width:2.2mm;height:2.2mm;background:var(--y);margin-right:1.8mm;vertical-align:.1mm;border-radius:50%}
ul.l,ol.l{margin:.6mm 0 2mm;padding-left:5mm}
ul.l li,ol.l li{margin:.5mm 0}
ul.l{list-style:none;padding-left:4mm}
ul.l>li{position:relative}
ul.l>li::before{content:"";position:absolute;left:-3.6mm;top:2.4mm;width:1.5mm;height:1.5mm;background:var(--p)}
ul.l>li.nb::before{display:none}
ul.l ul.l{margin:.4mm 0 .6mm}
ul.l ul.l>li::before{background:#fff;border:.3mm solid var(--p);width:1.4mm;height:1.4mm}
/* tables */
table.tb{width:100%;border-collapse:collapse;margin:1.6mm 0 3mm;font-size:10pt;line-height:1.45;background:#fff}
table.tb th{background:var(--p);color:#fff;border:.25mm solid var(--p);padding:1.3mm 1.6mm;font-weight:500;text-align:center;vertical-align:middle}
table.tb td{border:.25mm solid var(--line);padding:1.3mm 1.8mm;text-align:center;vertical-align:middle;background:#fff}
table.tb td.l,table.tb th.l{text-align:left}
table.tb td.b{font-weight:500}
table.tb caption{caption-side:top;text-align:left;font-size:10pt;font-weight:700;color:var(--pd);padding-bottom:1mm}
table.tb.f{table-layout:fixed}
/* notes */
.nt{margin:2.4mm 0 3.2mm;padding:3.2mm 3.2mm 1.4mm;border:.3mm solid var(--pl2);border-radius:2mm;background:var(--pl);break-inside:avoid;position:relative}
.nt>.lb{display:inline-block;font-size:10pt;font-weight:500;color:#fff;background:var(--p);border-radius:1mm;padding:0 2mm;margin:-5.4mm 0 1.2mm;line-height:1.55}
.nt p:last-child,.nt ul:last-child{margin-bottom:.6mm}
.nt.wa{border-color:#f3dd8c;background:var(--wl)}.nt.wa>.lb{color:#4a3600;background:var(--y)}
.nt.ds{background:#fff;border:.3mm solid var(--p)}
.nt.es{background:#fff;border:.3mm dashed var(--p)}
.eqn{margin:1.4mm 0 2.4mm;padding:1.8mm 3mm;text-align:center;font-size:12pt;font-weight:700;border-top:.3mm solid var(--p);border-bottom:.3mm solid var(--p);background:#fff;line-height:1.7}
.eqn small{display:block;font-size:10pt;font-weight:400;color:var(--gr);margin-top:.4mm}
.fg{margin:2mm 0 3mm;text-align:center;break-inside:avoid}
.fg svg,.fg img{max-width:100%;height:auto}
.fg .cap{font-size:10pt;color:var(--gr);margin-top:.6mm;text-align:center}
.two-c{display:grid;grid-template-columns:1fr 1fr;gap:4mm;align-items:start}
.tag{display:inline-block;font-size:10pt;font-weight:700;color:#fff;background:var(--p);padding:0 1.6mm;margin-right:1.2mm;line-height:1.5}
.tag.o{background:var(--wa)}
.tag.g{background:var(--gr)}
.sm{font-size:10pt;color:var(--gr)}
.mono{font-family:Pretendard,sans-serif}
/* cover & divider */
.cover{background:#fff}
.cover .grid{position:absolute;inset:0;background-image:linear-gradient(var(--pl2) .2mm,transparent .2mm),linear-gradient(90deg,var(--pl2) .2mm,transparent .2mm);background-size:7mm 7mm;opacity:.55;mask-image:linear-gradient(180deg,#000 0,#000 52%,transparent 78%);-webkit-mask-image:linear-gradient(180deg,#000 0,#000 52%,transparent 78%)}
.cover .band{position:absolute;left:0;right:0;top:0;height:11mm;background:var(--p)}
.cover .in{position:absolute;left:22mm;right:22mm;top:78mm}
.cover .sch{font-size:15pt;font-weight:700;color:var(--pd);letter-spacing:.8mm}
.cover h1{margin:6mm 0 0;font-size:41pt;line-height:1.28;font-weight:700;letter-spacing:-.3mm;color:var(--ink)}
.cover h1 span{color:var(--p)}
.cover .rule{width:34mm;height:1.4mm;background:var(--p);margin:9mm 0 7mm}
.cover .sub{font-size:15pt;font-weight:500;color:var(--ink);line-height:1.7}
.cover .rng{position:absolute;left:22mm;right:22mm;bottom:30mm;border-top:.3mm solid var(--p);padding-top:4mm;font-size:11.5pt;line-height:1.8;color:var(--ink)}
.cover .rng b{color:var(--pd)}
.divp{background:#fff}
.divp .bigno{position:absolute;left:20mm;top:42mm;font-size:150pt;line-height:1;font-weight:700;color:var(--p)}
.divp .bar{position:absolute;left:0;top:0;bottom:0;width:11mm;background:var(--p)}
.divp .tt{position:absolute;left:20mm;right:20mm;top:112mm}
.divp .tt .en{font-size:11pt;letter-spacing:.8mm;color:var(--pd);font-weight:700}
.divp .tt h1{font-size:32pt;line-height:1.3;margin:2mm 0 4mm;font-weight:700}
.divp .tt .ln{width:30mm;height:1.2mm;background:var(--p);margin-bottom:7mm}
.divp .idx .it{display:flex;gap:4mm;padding:2.2mm 0;border-bottom:.25mm solid var(--line);font-size:12.5pt;font-weight:700;align-items:baseline}
.divp .idx .it i{font-style:normal;color:var(--p);font-weight:700;min-width:14mm}
.divp .idx .it span{margin-left:auto;font-size:11pt;font-weight:500;color:var(--gr)}
.divp .ds{position:absolute;left:20mm;right:20mm;bottom:22mm;font-size:11pt;color:var(--gr);line-height:1.7}
/* toc */
.toc h1{font-size:25pt;font-weight:700;margin:0 0 5mm;border-top:1.4mm solid var(--p);padding-top:3mm}
.toc .r{display:flex;align-items:baseline;gap:3mm;padding:2mm 0;border-bottom:.25mm solid var(--line)}
.toc .r i{font-style:normal;min-width:11mm;font-size:15pt;font-weight:700;color:var(--p)}
.toc .r b{font-size:13.5pt;font-weight:700}
.toc .r .d{flex:1;border-bottom:.3mm dotted var(--gr);transform:translateY(-1mm);margin:0 1mm}
.toc .r .n{font-size:13pt;font-weight:700;color:var(--pd);min-width:11mm;text-align:right}
.toc .s{display:flex;align-items:baseline;gap:3mm;padding:.5mm 0 .5mm 14mm;font-size:10.5pt;color:var(--ink)}
.toc .s .d{flex:1;border-bottom:.3mm dotted var(--line);transform:translateY(-1mm)}
.toc .s .n{min-width:11mm;text-align:right;color:var(--gr)}
.toc .s em{font-style:normal;color:var(--gr);font-size:10pt;margin-left:2mm}
/* exam */
.q{break-inside:avoid;margin:0;padding-bottom:15mm;font-size:10.5pt;line-height:1.58}
.q .qh{display:flex;align-items:baseline;gap:2mm;margin-bottom:1.4mm}
.q .qn{font-size:13pt;font-weight:700;color:var(--ink);min-width:7mm}
.q .qp{font-size:10pt;color:var(--gr);font-weight:500}
.q .ut{margin-left:auto;font-size:10pt;color:var(--pd);font-weight:700}
.q .qs p{margin:0 0 1mm}
.q .fg{margin:1.2mm 0 1.8mm}
.q .eqn{font-size:11pt;padding:1.2mm 2mm;margin:1mm 0 1.6mm}
.bogi{position:relative;border:.3mm solid var(--ink);padding:3.2mm 2.6mm 1.2mm;margin:3.2mm 0 2mm}
.bogi .bt{position:absolute;top:-2.8mm;left:50%;transform:translateX(-50%);background:#fff;padding:0 2mm;font-size:10pt;font-weight:700}
.bogi p{margin:0 0 .8mm;padding-left:4.4mm;text-indent:-4.4mm}
.bxx{border:.3mm solid var(--ink);padding:1.6mm 2.6mm .8mm;margin:1.4mm 0 2mm;background:#fff}
.bxx p{margin:0 0 .8mm}
.bxx .bh{font-weight:700;margin-top:.6mm}
.chs{display:grid;grid-template-columns:1fr 1fr 1fr;gap:.6mm 1.4mm;margin-top:2mm;font-size:10.5pt}
.chs.v{grid-template-columns:1fr;gap:.8mm}
.chs.w{grid-template-columns:1fr 1fr}
.chs>div{display:flex;gap:1mm}
.chs>div>b{flex:none;font-weight:500}
.chs.v>div{padding-left:5mm;text-indent:-5mm;display:block}
.q table.tb{font-size:10pt;margin:1.4mm 0 2mm}
.q table.tb th{padding:.9mm 1.2mm}.q table.tb td{padding:.9mm 1.2mm}
.oxl{margin:1.6mm 0 0}
.oxl>div{display:flex;gap:1.2mm;padding:.5mm 0;border-bottom:.2mm dotted var(--line)}
.oxl .n{flex:none;min-width:7.5mm;font-weight:700}
.oxl .t{flex:1}
.oxl .a{flex:none;font-weight:500;white-space:nowrap}
.ans-area{height:11mm}
/* ox & blank */
.oxq{display:flex;gap:1.4mm;padding:1.4mm 0;border-bottom:.2mm dotted var(--line);font-size:10.5pt;line-height:1.55;break-inside:avoid}
.oxq .n{flex:none;min-width:8mm;font-weight:700;color:var(--pd)}
.oxq .t{flex:1}
.oxq .a{flex:none;white-space:nowrap;font-weight:500;color:var(--gr)}
.ugrp{margin:3mm 0 1.6mm;font-size:11pt;font-weight:700;color:var(--pd);border-bottom:.3mm solid var(--p);padding-bottom:.8mm;break-after:avoid}
.bl{display:inline-block;min-width:21mm;border-bottom:.3mm solid var(--ink);margin:0 .6mm;text-align:center;vertical-align:baseline;line-height:1.1;color:transparent}
.ansv .bl{color:var(--pd);font-weight:700;border-bottom-color:var(--p);background:linear-gradient(transparent 20%,var(--hl) 20%,var(--hl) 92%,transparent 92%)}
.bq{padding:1.6mm 0 1.6mm;border-bottom:.2mm dotted var(--line);display:flex;gap:1.6mm;break-inside:avoid;line-height:1.9}
.bq .n{flex:none;min-width:8mm;font-weight:700;color:var(--pd)}
.bq .t{flex:1}
/* solutions */
.sol{break-inside:avoid;margin:0 0 4.2mm;padding:0 0 2.4mm;border-bottom:.25mm solid var(--line);font-size:10pt;line-height:1.55}
.sol .sh{display:flex;gap:2mm;align-items:baseline;flex-wrap:wrap;margin-bottom:1mm}
.sol .sn{font-size:12pt;font-weight:700;color:var(--ink)}
.sol .sa{font-weight:700;color:#fff;background:var(--p);padding:0 1.8mm;font-size:10pt}
.sol .sa.t{background:var(--pd)}
.sol .ss{margin-left:auto;font-size:10pt;color:var(--gr);font-weight:500}
.sol p{margin:0 0 .8mm}
.sol .lb{font-weight:700;color:var(--pd)}
.sol .st{padding-left:4.6mm;text-indent:-4.6mm;margin:0 0 .5mm}
.sol .rv{margin-top:1.4mm;padding:1.3mm 2.4mm;background:var(--wl);border:.3mm solid #f3dd8c;border-radius:1.6mm}
.sol .rv .lb{color:#6a4d00}
.sol .sc{margin:1mm 0 .6mm;padding:1mm 2mm;border-radius:1.4mm;background:var(--pl)}
.solt{width:100%;border-collapse:collapse;font-size:10pt;margin:0 0 3mm}
.solt th{background:var(--p);color:#fff;padding:1mm 1.2mm;font-weight:700;text-align:center;border:.25mm solid var(--p)}
.solt td{border:.25mm solid var(--line);padding:1mm 1.4mm;vertical-align:middle;text-align:center;line-height:1.5}
.solt td.l{text-align:left}
/* grading */
.gr{margin:.8mm 0 .6mm;border:.25mm solid var(--p)}
.gr .gh{background:var(--p);color:#fff;font-weight:700;padding:.4mm 2mm;font-size:10pt}
.gr div.gi{padding:.5mm 2mm;border-top:.2mm solid var(--line)}
/* summary note */
.sn2{border:.3mm solid var(--p);margin:0 0 3.4mm;break-inside:avoid}
.sn2 .sh2{background:var(--p);color:#fff;padding:.9mm 3mm;font-weight:700;font-size:11.5pt}
.sn2 .sb{padding:1.8mm 3mm .6mm;font-size:10.5pt}
.sn2 .rr{display:flex;gap:2.4mm;padding:.9mm 0;border-bottom:.2mm dotted var(--line);align-items:baseline}
.sn2 .rr:last-child{border-bottom:0}
.sn2 .rr>b{flex:none;min-width:21mm;font-size:10pt;color:var(--pd);font-weight:700}
.sn2 .rr>span{flex:1}
.bk{display:inline-block;min-width:17mm;border-bottom:.3mm solid var(--ink);text-align:center;font-size:11pt;color:var(--gr);margin:0 .6mm;line-height:1.1}
.cover .ftr,.cover .hdr{display:none}
.toc{padding:18mm 20mm}
.toc .r em.dd{font-style:normal;font-size:9.5pt;color:var(--gr);font-weight:500}
/* v2 additions */
.q .qh{display:flex;align-items:baseline;gap:2mm;margin-bottom:1.2mm}
.q .qn{font-size:14pt;font-weight:700;color:var(--pd);min-width:8mm;line-height:1}
.q .qc{margin-left:auto;font-size:9pt;color:var(--gr);font-weight:400;letter-spacing:.1mm}
.th{display:flex;align-items:center;gap:2mm;margin:0 0 2.4mm;padding:1.4mm 2mm;background:var(--pl);border-radius:1.2mm;font-size:10pt;line-height:1.3}
.th i{font-style:normal;flex:none;min-width:5.6mm;height:5.6mm;line-height:5.6mm;text-align:center;background:var(--p);color:#fff;font-size:10pt;font-weight:700;border-radius:1mm;padding:0 1mm}
.th b{font-weight:700;color:var(--ink)}
.th span{margin-left:auto;color:var(--pd);font-weight:500;font-size:9.5pt;white-space:nowrap}
.grp{break-inside:avoid}
.go{margin:1.6mm 0 2.4mm;padding:1.4mm 3mm;border-radius:1.4mm;background:#fff8dc;border:.3mm solid #f3dd8c;font-size:10pt;color:#4a3600;line-height:1.5}
.go b{font-weight:700}
.go .gt{display:inline-block;background:var(--y);color:#3a2a00;font-weight:700;border-radius:1mm;padding:0 1.6mm;margin-right:1.6mm;font-size:9.5pt}
.subp{background:#fff}
.subp .bar{position:absolute;left:0;top:0;bottom:0;width:11mm;background:var(--p)}
.subp .bar::after{content:"";position:absolute;left:0;right:0;top:0;height:26mm;background:var(--y)}
.subp .sno{position:absolute;left:24mm;top:30mm;font-size:64pt;line-height:1;font-weight:700;color:var(--p);letter-spacing:-.5mm}
.subp .stt{position:absolute;left:24mm;right:20mm;top:60mm}
.subp .stt .en{font-size:10.5pt;letter-spacing:.8mm;color:var(--pd);font-weight:500}
.subp .stt h1{font-size:26pt;margin:2mm 0 3mm;font-weight:700;line-height:1.3}
.subp .ln{width:26mm;height:1.2mm;background:var(--y);margin:3mm 0 7mm}
.subp .rows .r{display:flex;gap:3mm;align-items:center;padding:2.1mm 0;border-bottom:.25mm solid var(--line);font-size:11.5pt}
.subp .rows .r i{font-style:normal;flex:none;width:7mm;height:7mm;line-height:7mm;text-align:center;background:var(--p);color:#fff;font-weight:700;border-radius:1.2mm;font-size:11pt}
.subp .rows .r b{font-weight:500}
.subp .rows .r span{margin-left:auto;color:var(--pd);font-size:10.5pt;font-weight:500;white-space:nowrap}
.subp .tip{position:absolute;left:24mm;right:20mm;bottom:22mm;font-size:10.5pt;color:var(--gr);line-height:1.7;border-top:.3mm solid var(--line);padding-top:3mm}
table.qa{width:100%;border-collapse:collapse;margin:0 0 3mm;font-size:10pt;table-layout:fixed}
table.qa td{border:.25mm solid var(--line);padding:.9mm .6mm;text-align:center;line-height:1.35}
table.qa td b{font-weight:500;color:var(--pd);margin-right:.8mm}
table.qa td.e{background:#fafafa}
.qah{margin:2mm 0 1.6mm;font-size:11pt;font-weight:700;display:flex;gap:2mm;align-items:center}
.qah i{font-style:normal;background:var(--y);color:#3a2a00;padding:0 2mm;border-radius:1mm;font-size:10pt}
.sol .sc2{margin-left:auto;font-size:9pt;color:var(--gr)}
/* weights: default regular */
h2.sec,h3.sub,h4,.nt>.lb,.sol .sn{font-weight:700}
b,strong{font-weight:500}
.cover .band,.cover .grid{display:none}
.cover2{position:absolute;inset:0;background:#fff;overflow:hidden}
.cover2 .top{position:absolute;left:0;right:0;top:0;height:176mm;background:linear-gradient(135deg,#1f7d4e 0%,#2f9d66 62%,#31bb76 100%)}
.cover2 .sun{position:absolute;right:-26mm;top:116mm;width:96mm;height:96mm;border-radius:50%;background:var(--y)}
.cover2 .sun2{position:absolute;right:30mm;top:152mm;width:28mm;height:28mm;border-radius:50%;background:#fff;opacity:.92}
.cover2 svg.crv{position:absolute;left:0;top:0;width:210mm;height:176mm}
.cover2 .lab{position:absolute;left:22mm;top:24mm;color:#dcfbec;font-size:10.5pt;letter-spacing:1.2mm;font-weight:500}
.cover2 .sch{position:absolute;left:22mm;top:33mm;color:#fff;font-size:15pt;font-weight:500}
.cover2 h1{position:absolute;left:22mm;top:66mm;margin:0;color:#fff;font-size:50pt;line-height:1.18;font-weight:700;letter-spacing:-.4mm}
.cover2 h1 em{font-style:normal;background:linear-gradient(transparent 58%,var(--y) 58%,var(--y) 92%,transparent 92%);padding:0 1mm}
.cover2 .sub{position:absolute;left:22mm;top:140mm;color:#eafdf3;font-size:14pt;font-weight:400;line-height:1.7}
.cover2 .rg{position:absolute;left:22mm;right:22mm;top:196mm}
.cover2 .rg .t{font-size:10.5pt;letter-spacing:.8mm;color:var(--pd);font-weight:500;margin-bottom:2mm}
.cover2 .rg .u{display:flex;gap:3mm;align-items:center;padding:2.2mm 0;border-bottom:.3mm solid var(--line);font-size:14pt}
.cover2 .rg .u i{font-style:normal;flex:none;width:11mm;height:9mm;line-height:9mm;text-align:center;background:var(--p);color:#fff;font-weight:700;border-radius:1.4mm;font-size:13pt}
